    n = int(N)
    d = 1
    p = 2
    while p * p <= n:
        cnt = 0
        while n % p == 0:
            n //= p
            cnt += 1
        if cnt >= 2:
            d *= p ** (cnt // 2)
        p += 1 if p == 2 else 2
    sqfree = n
    return d, sqfree

